// Leçon 0.1 — LED protégée par une résistance de 220 Ω sur la broche D9
const int BROCHE_LED = 9;

void setup() {
  pinMode(BROCHE_LED, OUTPUT);   // la broche D9 devient une sortie
}

void loop() {
  digitalWrite(BROCHE_LED, HIGH); // D9 à 5 V : I ≈ (5 - 2) / 220 ≈ 13,6 mA, la LED s'allume
  delay(1000);                    // attendre 1 seconde
  digitalWrite(BROCHE_LED, LOW);  // D9 à 0 V : plus de courant, la LED s'éteint
  delay(1000);
}
